package com.bank.orderedgen;

import java.util.logging.*;

public class OrderedGenDemo {
    private static final Logger log = Logger.getLogger("OrderedGen");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        OrderedGenerateService service = new OrderedGenerateService();
        log.info("five x's (parallel, ordered):");
        service.fiveXs();
    }
}

// ─── Would be in service/OrderedGenerateService.java ───
class OrderedGenerateService {
    void fiveXs() {
        java.util.stream.Stream.generate(() -> "x")   // INFINITE: "x", "x", ...
            .limit(5)                                   // bound → exactly 5
            .parallel()                                 // request parallel execution
            .forEachOrdered(System.out::println);       // encounter order preserved
    }
}
